/**
 * scripts/fragment_and_package_conversations.js
 * 
 * Reads conversation.json, fragments into individual chat files,
 * filters personal data (emails, phones, names, URLs) and domain-specific content
 * based on YAML filter definitions, zips fragments into GenesisAeonZIPMEM/,
 * and generates a mapping file with processing directives.
 * Also exports a helper function to deposit new content with rules.
 */

const fs = require('fs');
const path = require('path');
const archiver = require('archiver');
const yaml = require('js-yaml');

// Configuration
const INPUT_FILE = path.join(__dirname, '../data/conversation.json');
const OUTPUT_DIR = path.join(__dirname, '../GenesisAeonZIPMEM');
const MAPPING_FILE = path.join(OUTPUT_DIR, 'mapping.json');
const FILTER_CONFIG_DIR = path.join(__dirname, '../config/filter-config');

// Utility: personal data filter (regex-based)
function sanitizeText(text) {
  return text
    .replace(/https?:\/\/\S+/gi, '[REDACTED_URL]')
    .replace(/www\.\S+/gi, '[REDACTED_URL]')
    .replace(/\b[\w.+-]+@[\w.-]+\.[a-zA-Z]{2,}\b/g, '[REDACTED_EMAIL]')
    .replace(/\b\+?[0-9][0-9()\-\s]{7,}\b/g, '[REDACTED_PHONE]')
    .replace(/\b[A-Z][a-z]+ [A-Z][a-z]+\b/g, '[REDACTED_NAME]');
}

// Load YAML filter configurations
function loadFilterConfigs() {
  const configs = [];
  if (!fs.existsSync(FILTER_CONFIG_DIR)) return configs;
  fs.readdirSync(FILTER_CONFIG_DIR).forEach(file => {
    if (file.endsWith('.yaml') || file.endsWith('.yml')) {
      const cfg = yaml.load(fs.readFileSync(path.join(FILTER_CONFIG_DIR, file), 'utf8'));
      configs.push(cfg);
    }
  });
  return configs;
}

// Apply domain-specific filters to messages
function applyDomainFilters(messages, configs) {
  return messages.filter(msg => {
    for (const cfg of configs) {
      const domain = cfg.domain;
      if (msg.content.includes(domain)) return true;
    }
    return false;
  });
}

async function fragmentAndPackage() {
  const data = JSON.parse(fs.readFileSync(INPUT_FILE, 'utf8'));
  if (!fs.existsSync(OUTPUT_DIR)) fs.mkdirSync(OUTPUT_DIR, { recursive: true });

  const filterConfigs = loadFilterConfigs();
  const mapping = [];

  // Group and process chats
  const chats = data.messages.reduce((acc, msg) => {
    const id = msg.chatId || 'unknown';
    acc[id] = acc[id] || [];
    acc[id].push(msg);
    return acc;
  }, {});

  for (const [chatId, msgs] of Object.entries(chats)) {
    let processed = msgs.map(m => ({ ...m, content: sanitizeText(m.content) }));
    // Domain filtering if configs exist
    if (filterConfigs.length) processed = applyDomainFilters(processed, filterConfigs);

    const filename = `chat_${chatId}.json`;
    const filepath = path.join(OUTPUT_DIR, filename);
    fs.writeFileSync(filepath, JSON.stringify(processed, null, 2));
    mapping.push({ chatId, file: filename, processor: filterConfigs.length ? 'domainFilter' : 'fragmentAndSanitize' });
  }

  // Zip chat fragments
  const zipPath = path.join(OUTPUT_DIR, 'chats_bundle.zip');
  const output = fs.createWriteStream(zipPath);
  const archive = archiver('zip', { zlib: { level: 9 } });
  output.on('close', () => console.log(`ZIP created: ${zipPath} (${archive.pointer()} bytes)`));
  archive.pipe(output);
  fs.readdirSync(OUTPUT_DIR)
    .filter(f => f.startsWith('chat_') && f.endsWith('.json'))
    .forEach(f => archive.file(path.join(OUTPUT_DIR, f), { name: f }));
  await archive.finalize();

  // Write mapping file
  fs.writeFileSync(MAPPING_FILE, JSON.stringify(mapping, null, 2));
  console.log(`Mapping file written to ${MAPPING_FILE}`);
}

// Helper to deposit content with rules
function depositContent(folder, contentObj, rules) {
  const targetDir = path.join(OUTPUT_DIR, folder);
  if (!fs.existsSync(targetDir)) fs.mkdirSync(targetDir, { recursive: true });
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
  const filename = `content_${timestamp}.json`;
  fs.writeFileSync(
    path.join(targetDir, filename),
    JSON.stringify({ metadata: rules, content: contentObj }, null, 2)
  );
  console.log(`Deposited content to ${path.join(folder, filename)}`);
}

if (require.main === module) {
  fragmentAndPackage().catch(err => console.error(err));
}

module.exports = { fragmentAndPackage, depositContent };
